        {kind === "ai" && <><rect x="6" y="6" width="12" height="12" rx="3" /><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4M10 10h4v4h-4z" /><circle cx="12" cy="12" r=".8" fill={accent} stroke={accent} /></>}
