/**
 * @framerIntrinsicWidth 488
 * @framerIntrinsicHeight 333
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 */
export default function NimbusFeatureMotion({ mode = "Routing", accent = "#FF7828", speed = 1, style }: Props) {
    const root = React.useRef<HTMLDivElement>(null)
    const svgRef = React.useRef<SVGSVGElement>(null)
    const staticRenderer = useIsStaticRenderer()
    const [active, setActive] = React.useState(false)
    const id = React.useId().replace(/:/g, "")
    const glow = `nfm-glow-${id}`
    const beam = `nfm-beam-${id}`
    const rate = Math.max(0.25, Math.min(2, speed))

    React.useEffect(() => {
        if (staticRenderer || typeof window === "undefined" || !root.current) return
        const reduced = window.matchMedia("(prefers-reduced-motion: reduce)")
        let intersecting = false
        const update = () => setActive(intersecting && !document.hidden && !reduced.matches)
        const observer = new IntersectionObserver(entries => { intersecting = entries[0]?.isIntersecting ?? false; update() }, { rootMargin: "60px" })
        observer.observe(root.current)
        document.addEventListener("visibilitychange", update)
        reduced.addEventListener("change", update)
        return () => { observer.disconnect(); document.removeEventListener("visibilitychange", update); reduced.removeEventListener("change", update) }
    }, [staticRenderer])

    React.useEffect(() => {
        const svg = svgRef.current
        if (!svg) return
        if (active) svg.unpauseAnimations?.()
        else { svg.pauseAnimations?.(); if (staticRenderer) svg.setCurrentTime?.(1.2) }
    }, [active, mode, staticRenderer])

    const playing: React.CSSProperties = { animationPlayState: active ? "running" : "paused" }
    const defs = <defs>
        <filter id={glow} x="-250%" y="-250%" width="600%" height="600%"><feGaussianBlur stdDeviation="3.2" /></filter>
        <linearGradient id={beam}><stop stopColor={accent} stopOpacity="0" /><stop offset=".55" stopColor={accent} /><stop offset="1" stopColor="#FFFFFF" /></linearGradient>
    </defs>

    return <div ref={root} aria-hidden="true" style={{ ...style, position: "relative", width: "100%", height: "100%", overflow: "hidden", pointerEvents: "none" }}>
        <style>{`
            @keyframes nfm-slider { from {transform:translateY(0px)} to {transform:translateY(150px)} }
            @keyframes nfm-row { from {transform:translateX(0px)} to {transform:translateX(-480px)} }
            .nfm-knob {will-change:transform}
            .nfm-track {display:flex;width:max-content;will-change:transform;animation:nfm-row linear infinite}
            .nfm-icon-segment {display:flex;gap:16px;padding-right:16px;flex-shrink:0}
            @media(prefers-reduced-motion:reduce) {.nfm-knob,.nfm-track {animation-play-state:paused!important}}
        `}</style>
        {mode === "Routing" && <svg ref={svgRef} width="100%" height="100%" viewBox="0 0 584 467" preserveAspectRatio="xMidYMid meet" style={{ overflow: "visible" }}>
            {defs}
            <path d="M0.0099 145.49L224.307 0L583.485 164.181L328.878 466.275L0.0099 247.535L120.241 0L583.485 96.4881L0.0099 201.059L583.485 423.335L70.229 0L120.241 466.275L432.438 0L492.554 466.275" stroke="white" strokeOpacity=".075" strokeWidth="1.01" fill="none" />
            {ROUTES.map((path, index) => <g key={path}>
                <rect x="-14" y="-2.8" width="25" height="5.6" rx="2.8" fill={accent} filter={`url(#${glow})`} opacity=".7" />
                <rect x="-14" y="-1.1" width="25" height="2.2" rx="1.1" fill={`url(#${beam})`} />
                <animateMotion path={path} dur={`${(4.1 + index * .47) / rate}s`} begin={`${(-index * .83).toFixed(2)}s`} rotate="auto" repeatCount="indefinite" />
            </g>)}
        </svg>}
        {mode === "NURA" && <svg ref={svgRef} width="100%" height="100%" viewBox="0 0 250 236" preserveAspectRatio="xMidYMid meet" fill="none">
            {defs}
            <g fill="none" dangerouslySetInnerHTML={{ __html: BRAIN_LINES }} />
            {CIRCUITS.map((path, index) => <g key={path}>
                <circle r="10" fill={accent} opacity=".75" filter={`url(#${glow})`} />
                <circle r="4.1" fill="#FFF6ED" />
                <animateMotion path={path} dur={`${(4.2 + index * .65) / rate}s`} begin={`${(-index * 1.4).toFixed(2)}s`} repeatCount="indefinite" />
            </g>)}
        </svg>}
        {mode === "Controls" && <svg width="100%" height="100%" viewBox="0 0 317 220" preserveAspectRatio="xMidYMid meet">
            {defs}
            {[80, 158.5, 237].map((x, index) => <g key={x}>
                <rect x={x - 15} y="17" width="30" height="184" rx="15" fill="#FFFFFF" fillOpacity=".07" stroke="#FFFFFF" strokeOpacity=".2" />
                <path d={`M${x} 30V188`} stroke="#FFFFFF" strokeWidth="4" strokeOpacity=".65" />
                <g transform={`translate(${x},30)`}>
                    <g className="nfm-knob" style={{ ...playing, animation: `nfm-slider ${(4.5 + index * .9) / rate}s ease-in-out ${-index * 1.8}s infinite alternate`, animationPlayState: active ? "running" : "paused" }}>
                        <circle r="14" fill={accent} filter={`url(#${glow})`} opacity=".85" />
                        <circle r="8.5" fill={accent} /><circle r="4.8" fill="#FFF8F0" />
                    </g>
                </g>
            </g>)}
        </svg>}
        {mode === "Connection" && <div style={{ height: "100%", display: "flex", flexDirection: "column", justifyContent: "center", gap: 16, maskImage: "linear-gradient(90deg,transparent,#000 10%,#000 90%,transparent)", WebkitMaskImage: "linear-gradient(90deg,transparent,#000 10%,#000 90%,transparent)" }}>
            {ICON_ROWS.map((icons, index) => <div key={index} style={{ overflow: "hidden", height: 64, flexShrink: 0 }}>
                <div className="nfm-track" style={{ ...playing, animationDuration: `${(22 + index * 4) / rate}s`, animationDirection: index ? "reverse" : "normal", animationDelay: `${-index * 7}s` }}>
                    {[0, 1, 2].map(copy => <div className="nfm-icon-segment" key={copy}>
                        {icons.map(kind => <div key={kind} style={{ width: 64, height: 64, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, border: "1px solid rgba(255,255,255,.2)", borderRadius: 18, background: "rgba(255,255,255,.04)", boxShadow: "inset 0 1px 0 rgba(255,255,255,.06)" }}><DataIcon kind={kind} accent={accent} /></div>)}
                    </div>)}
                </div>
            </div>)}
        </div>}
    </div>
}

addPropertyControls(NimbusFeatureMotion, {
    mode: { type: ControlType.Enum, title: "Visual", options: ["Routing", "NURA", "Controls", "Connection"], defaultValue: "Routing" },
    accent: { type: ControlType.Color, title: "Light", defaultValue: "#FF7828" },
    speed: { type: ControlType.Number, title: "Speed", defaultValue: 1, min: .25, max: 2, step: .05 },
})
